// ============================================================
// GrassToolboxFilterProxy
// ============================================================
GrassToolboxFilterProxy::GrassToolboxFilterProxy( QObject *parent )
    : QSortFilterProxyModel( parent )
{
    setFilterCaseSensitivity( Qt::CaseInsensitive );
    setRecursiveFilteringEnabled( true );  // Qt 5.10+ / Qt 6
}

bool GrassToolboxFilterProxy::filterAcceptsRow( int sourceRow,
                                                 const QModelIndex &sourceParent ) const
{
    // With setRecursiveFilteringEnabled(true), Qt handles child propagation.
    // We only need to match on the Search role.
    const QModelIndex idx = sourceModel()->index( sourceRow, 0, sourceParent );
    const QString searchText = idx.data( Qt::UserRole + 1 ).toString();
    const QRegularExpression re = filterRegularExpression();
    return re.pattern().isEmpty() || re.match( searchText ).hasMatch();
}

bool GrassToolboxFilterProxy::anyChildMatches( const QModelIndex &parent ) const
{
    // Not called when setRecursiveFilteringEnabled is on, kept for clarity
    const int rows = sourceModel()->rowCount( parent );
    for ( int r = 0; r < rows; ++r )
    {
        const QModelIndex child = sourceModel()->index( r, 0, parent );
        if ( filterAcceptsRow( r, parent ) ) return true;
        if ( sourceModel()->hasChildren( child ) && anyChildMatches( child ) ) return true;
    }
    return false;
}

// ============================================================
// GrassToolboxTree
// ============================================================
GrassToolboxTree::GrassToolboxTree( QWidget *parent )
    : QWidget( parent )
{
    QVBoxLayout *lay = new QVBoxLayout( this );
    lay->setContentsMargins( 0, 0, 0, 0 );
    lay->setSpacing( 2 );

    // Search box
    mSearch = new QLineEdit( this );
    mSearch->setPlaceholderText( "Search modules…" );
    mSearch->setClearButtonEnabled( true );
    lay->addWidget( mSearch );

    // Tree view
    mModel = new QStandardItemModel( 0, 1, this );
    mModel->setHorizontalHeaderLabels( { "Module" } );

    mProxy = new GrassToolboxFilterProxy( this );
    mProxy->setSourceModel( mModel );

    mTree = new QTreeView( this );
    mTree->setModel( mProxy );
    mTree->setHeaderHidden( true );
    mTree->setUniformRowHeights( true );
    mTree->setAnimated( true );
    mTree->setAlternatingRowColors( false );
    mTree->setEditTriggers( QAbstractItemView::NoEditTriggers );
    mTree->setSelectionMode( QAbstractItemView::SingleSelection );
    mTree->setExpandsOnDoubleClick( false );  // we handle double-click ourselves
    lay->addWidget( mTree, 1 );

    connect( mSearch, &QLineEdit::textChanged,
             this, &GrassToolboxTree::onFilterChanged );
    connect( mTree, &QTreeView::activated,
             this, &GrassToolboxTree::onItemActivated );
    connect( mTree, &QTreeView::doubleClicked,
             this, &GrassToolboxTree::onItemActivated );

    // Load default tree
    loadModules();
}

// ---------------------------------------------------------------------------
// loadModules
// ---------------------------------------------------------------------------
bool GrassToolboxTree::loadModules( const QString &xmlPath )
{
    QString path = xmlPath;
    if ( path.isEmpty() )
    {
        const QString gisBase = QString::fromLocal8Bit( qgetenv( "GISBASE" ) );
        if ( gisBase.isEmpty() )
        {
            qCWarning(lcToolbox) << "GrassToolboxTree: GISBASE not set";
            return false;
        }
        path = gisBase + "/gui/wxpython/xml/module_tree_menudata.xml";
    }

    QFile f( path );
    if ( !f.open( QIODevice::ReadOnly ) )
    {
        qCWarning(lcToolbox) << "GrassToolboxTree: cannot open" << path;
        return false;
    }

    QDomDocument doc;
    const auto result = doc.setContent( &f );
    f.close();
    if ( !result )
    {
        qCWarning(lcToolbox) << "GrassToolboxTree: XML parse error:" << result.errorMessage;
        return false;
    }

    mModel->clear();
    mModel->setHorizontalHeaderLabels( { "Module" } );

    const QDomElement root    = doc.documentElement();           // <menudata>
    const QDomElement menubar = root.firstChildElement( "menubar" ); // <menubar>
    if ( menubar.isNull() )
    {
        qCWarning(lcToolbox) << "GrassToolboxTree: no <menubar> element";
        return false;
    }

    // Top-level menus (Import/Export, Raster, Vector, …)
    QDomElement menu = menubar.firstChildElement( "menu" );
    while ( !menu.isNull() )
    {
        const QString label = menu.firstChildElement( "label" ).text().trimmed();
        // Strip & accelerator marks
        const QString cleanLabel = QString( label ).remove( '&' );

        QStandardItem *topItem = new QStandardItem( cleanLabel );
        topItem->setData( "",        static_cast<int>( Role::Command ) );
        topItem->setData( cleanLabel.toLower(), static_cast<int>( Role::Search ) );
        topItem->setEditable( false );

        QFont f = topItem->font();
        f.setBold( true );
        topItem->setFont( f );
        topItem->setForeground( QColor( "#2c6496" ) );

        const QDomElement items = menu.firstChildElement( "items" );
        if ( !items.isNull() )
            populateModel( items, topItem );

        mModel->appendRow( topItem );
        menu = menu.nextSiblingElement( "menu" );
    }

    // Expand the first level so users see the top categories
    mTree->expandToDepth( 0 );

    const int total = mModel->rowCount();
    qCInfo(lcToolbox) << "GrassToolboxTree: loaded" << total << "top-level sections from" << path;

    // Append Display Layers section (native d.* composites) and Add-ons
    addNativeDisplaySection();
    loadAddons();

    return true;
}

// ---------------------------------------------------------------------------
// addNativeDisplaySection — prepend a "Display Layers" section for native d.*
// ---------------------------------------------------------------------------
void GrassToolboxTree::addNativeDisplaySection()
{
    // Each entry: { display command, human label, keywords for search }
    static const struct { const char *cmd; const char *label; const char *kw; } kItems[] = {
        { "d.rgb",           "RGB Composite",            "rgb composite colour bands"          },
        { "d.ihs",           "IHS Composite",            "ihs intensity hue saturation colour" },
        { "d.shade",         "Shaded Relief",            "shade hillshade relief blend"        },
        { "d.rast.num",      "Cell Values",              "raster numbers values labels cells"  },
        { "d.rast.arrow",    "Flow / Aspect Arrows",     "arrows flow aspect direction vector" },
        { "d.vect.thematic", "Thematic Choropleth",      "thematic choropleth classify colour" },
        { "d.vect.chart",    "Feature Charts",           "chart pie bar attribute statistics"  },
        { "d.label",         "Attribute Labels",         "label text annotation font"          },
        { "d.geodesic",      "Great Circle (Geodesic)",  "geodesic great circle line sphere"   },
        { "d.rhumbline",     "Rhumb Line (Loxodrome)",   "rhumb loxodrome bearing constant"    },
    };

    auto *top = new QStandardItem( "Display Layers" );
    top->setData( "",                    static_cast<int>( Role::Command ) );
    top->setData( "display layers",      static_cast<int>( Role::Search  ) );
    top->setEditable( false );
    {
        QFont f = top->font();
        f.setBold( true );
        top->setFont( f );
        top->setForeground( QColor( "#2c7a2c" ) );
    }

    for ( const auto &e : kItems )
    {
        const QString display = QString( "%1  (%2)" ).arg( e.label, e.cmd );
        auto *item = new QStandardItem( display );
        item->setData( QString( e.cmd ), static_cast<int>( Role::Command ) );
        item->setData( ( QString( e.label ) + " " + e.cmd + " " + e.kw ).toLower(),
                       static_cast<int>( Role::Search ) );
        item->setToolTip( QString( "Native Qt composite layer — opens the Add Layer dialog." ) );
        item->setEditable( false );
        top->appendRow( item );
    }

    // Insert as the first section so it is immediately visible
    mModel->insertRow( 0, top );
}

// ---------------------------------------------------------------------------
// loadAddons — append all grass-addons as a searchable "Add-ons" section
// ---------------------------------------------------------------------------
void GrassToolboxTree::loadAddons()
{
#ifndef HAVE_GRASS_ADDONS
    return;   // addons not available in this build
#else
    const auto &addons = GrassAddons::allAddons();
    if ( addons.isEmpty() ) return;

    // Group addons by their top-level menu path (first path component)
    // so the section mirrors the menu structure.
    QMap<QString, QStandardItem *> groups;

    auto *top = new QStandardItem( QString( "Add-ons  (%1)" ).arg( addons.size() ) );
    top->setData( "",         static_cast<int>( Role::Command ) );
    top->setData( "add-ons addons extensions grass-addons",
                  static_cast<int>( Role::Search ) );
    top->setEditable( false );
    {
        QFont f = top->font();
        f.setBold( true );
        top->setFont( f );
        top->setForeground( QColor( "#7a4c2c" ) );
    }

    for ( const GrassAddons::AddonInfo &a : addons )
    {
        const QString name  = QString::fromUtf8( a.name  );
        const QString label = QString::fromUtf8( a.label );
        const QString path  = QString::fromUtf8( a.menuPath );

        // Top-level group = first path component before '/'
        const QString groupKey = path.section( '/', 0, 0 ).trimmed();
        const QString groupLabel = groupKey.isEmpty() ? "Other" : groupKey;

        if ( !groups.contains( groupKey ) )
        {
            auto *grp = new QStandardItem( groupLabel );
            grp->setData( "", static_cast<int>( Role::Command ) );
            grp->setData( groupLabel.toLower(), static_cast<int>( Role::Search ) );
            grp->setEditable( false );
            {
                QFont f = grp->font();
                f.setItalic( true );
                grp->setFont( f );
            }
            top->appendRow( grp );
            groups[groupKey] = grp;
        }

        const QString display = label.isEmpty()
                                ? name
                                : QString( "%1  (%2)" ).arg( label, name );
        auto *item = new QStandardItem( display );
        item->setData( name, static_cast<int>( Role::Command ) );
        item->setData( ( name + " " + label ).toLower(),
                       static_cast<int>( Role::Search ) );
        item->setEditable( false );
        if ( a.isNew )
            item->setForeground( QColor( "#c08000" ) );
        groups[groupKey]->appendRow( item );
    }

    mModel->appendRow( top );
    qCInfo(lcToolbox) << "GrassToolboxTree: loaded" << addons.size() << "addons";
#endif
}

// ---------------------------------------------------------------------------
// populateModel — recurse through <items>
// ---------------------------------------------------------------------------
void GrassToolboxTree::populateModel( const QDomElement &items,
                                       QStandardItem *parent )
{
    QDomElement child = items.firstChildElement();
    while ( !child.isNull() )
    {
        const QString tag = child.tagName();

        if ( tag == "menu" )
        {
            // Sub-group
            const QString label = child.firstChildElement( "label" ).text().trimmed()
                                       .remove( '&' );

            QStandardItem *groupItem = new QStandardItem( label );
            groupItem->setData( "",       static_cast<int>( Role::Command ) );
            groupItem->setData( label.toLower(), static_cast<int>( Role::Search ) );
            groupItem->setEditable( false );

            QFont f = groupItem->font();
            f.setItalic( true );
            groupItem->setFont( f );

            const QDomElement subItems = child.firstChildElement( "items" );
            if ( !subItems.isNull() )
                populateModel( subItems, groupItem );

            parent->appendRow( groupItem );
        }
        else if ( tag == "menuitem" )
        {
            const QString label   = child.firstChildElement( "label" ).text().trimmed();
            const QString command = child.firstChildElement( "command" ).text().trimmed();
            const QString help    = child.firstChildElement( "help" ).text().trimmed();
            const QString kw      = child.firstChildElement( "keywords" ).text().trimmed();

            if ( command.isEmpty() )
            {
                child = child.nextSiblingElement();
                continue;
            }

            // Display: "label (command)" so both are visible without tooltip
            const QString display = label.isEmpty()
                                    ? command
                                    : QString( "%1  (%2)" ).arg( label, command );

            QStandardItem *item = new QStandardItem( display );
            item->setData( command, static_cast<int>( Role::Command ) );

            // Search role: label + command + keywords, lower-case, space-joined
            const QString searchStr = ( label + " " + command + " " + kw ).toLower();
            item->setData( searchStr, static_cast<int>( Role::Search ) );

            item->setToolTip( help.isEmpty() ? command : help );
            item->setEditable( false );

            parent->appendRow( item );
        }
        // <separator/> and other tags are skipped

        child = child.nextSiblingElement();
    }
}

// ---------------------------------------------------------------------------
// Slots
// ---------------------------------------------------------------------------
void GrassToolboxTree::onFilterChanged( const QString &text )
{
    mProxy->setFilterRegularExpression(
        QRegularExpression( QRegularExpression::escape( text ),
                            QRegularExpression::CaseInsensitiveOption ) );

    if ( text.isEmpty() )
    {
        mTree->collapseAll();
        mTree->expandToDepth( 0 );
    }
    else
    {
        mTree->expandAll();
    }
}

void GrassToolboxTree::onItemActivated( const QModelIndex &proxyIndex )
{
    if ( !proxyIndex.isValid() ) return;

    const QModelIndex srcIndex = mProxy->mapToSource( proxyIndex );
    const QStandardItem *item = mModel->itemFromIndex( srcIndex );
    if ( !item ) return;

    const QString command = item->data( static_cast<int>( Role::Command ) ).toString();

    if ( command.isEmpty() )
    {
        // Group node — toggle expand/collapse
        if ( mTree->isExpanded( proxyIndex ) )
            mTree->collapse( proxyIndex );
        else
            mTree->expand( proxyIndex );
        return;
    }

    emit moduleActivated( command );
}
